def comps(g):
    h,w=len(g),len(g[0]); bg=g[0][0]; vis=[[False]*w for _ in range(h)]; out=[]
    for r in range(h):
        for c in range(w):
            if g[r][c]!=bg and not vis[r][c]:
                col=g[r][c]; q=deque([(r,c)]); vis[r][c]=True; cells=set()
                while q:
                    y,x=q.popleft(); cells.add((y,x))
                    for dy,dx in((-1,0),(1,0),(0,-1),(0,1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and not vis[ny][nx] and g[ny][nx]==col:
                            vis[ny][nx]=True; q.append((ny,nx))
                out.append(cells)
    return out
