    for r in range(H):
        for c in range(W):
            if g[r][c]==bg:
                # nearest marks left/right/up/down
                L=[x for x in range(c-1,-1,-1) if g[r][x]==sc]; R=[x for x in range(c+1,W) if g[r][x]==sc]
                U=[y for y in range(r-1,-1,-1) if g[y][c]==sc]; D=[y for y in range(r+1,H) if g[y][c]==sc]
